import React, {useState} from "react";
import {Alert, Autocomplete, Button, Checkbox, CircularProgress, Dialog, DialogActions, DialogContent, DialogTitle, FormControlLabel, Paper, Stack, TextField, Typography} from "@mui/material";
import {Link} from "react-router-dom";
import {useAuth} from "../../auth/AuthContext";
import {getApiErrorMessage} from "../../api/errors";
import useDebounce from "../../hooks/useDebounce";
import {MainDiv,PageTitle} from "../../ui/commonStyled/commonStyled";
import {StockAlertRule, useActiveStockAlertsQuery, useSaveStockAlertMutation, useStockAlertRecipientsQuery, useStockAlertRulesQuery} from "./stockAlertsApi";

export function stockThreshold(value: string): number | null {
    const text = value.trim().replace(",",".");
    if (!/^\d+(?:\.\d{1,6})?$/.test(text)) return null;
    const number = Number(text); return Number.isFinite(number) && number >= 0 && number <= 1e12 ? number : null;
}
export default function StockAlertsPage() {
    const {isCompanyAdmin} = useAuth(); const [query,setQuery] = useState(""); const term = useDebounce(query);
    const rules = useStockAlertRulesQuery(term,{pollingInterval:30000}); const active = useActiveStockAlertsQuery(undefined,{pollingInterval:10000}); const recipients = useStockAlertRecipientsQuery();
    const [editing,setEditing] = useState<StockAlertRule | null>(null); const [threshold,setThreshold] = useState("");
    const [error,setError] = useState(""); const [notice,setNotice] = useState(""); const [save,state] = useSaveStockAlertMutation();
    const open = (rule: StockAlertRule) => {setEditing({...rule,enabled:rule.enabled || rule.version === 0}); setThreshold(String(rule.threshold));setError("");setNotice("");};
    const commit = async () => {
        if (!editing) return; const amount = stockThreshold(threshold);
        if (amount === null) {setError("Порог должен быть неотрицательным числом, до 6 знаков после запятой."); return;}
        try {await save({productId:editing.productId,threshold:amount,enabled:editing.enabled,notifyTelegram:editing.notifyTelegram,recipientUserIds:editing.recipientUserIds,version:editing.version}).unwrap();setEditing(null);setNotice("Порог сохранён. Актуальные напоминания появятся в списке.");}
        catch (failure) {setError(getApiErrorMessage(failure,"Не удалось сохранить настройки."));}
    };
    return <MainDiv><Stack spacing={2}><PageTitle>Закупки и низкие остатки</PageTitle>
        <Typography>Укажите порог товара. При остатке, равном порогу или ниже, CRM напомнит о закупке. Проверка выполняется каждые 30 секунд при работающем сервере.</Typography>
        <Alert severity="info">Одно напоминание создаётся на период низкого остатка. После пополнения выше порога следующий спад создаст новое напоминание.</Alert>
        {notice && <Alert severity="success">{notice}</Alert>}
        <Typography variant="h6">Нужно закупить</Typography>{active.isLoading && <CircularProgress/>}{active.isError && <Alert severity="error">Не удалось загрузить напоминания. <Button onClick={() => void active.refetch()}>Повторить</Button></Alert>}
        {active.data?.length === 0 && <Typography>Товаров с низким остатком по настроенным порогам нет.</Typography>}
        {active.data?.map(alert => <Paper key={alert.id} variant="outlined" sx={{p:2}}><Stack spacing={1}><Typography fontWeight={700}>{alert.name}</Typography><Typography>Остаток: {alert.currentStock} · Порог: {alert.threshold} · GTIN {alert.gtin}</Typography>
            {(alert.telegramQueued > 0 || alert.telegramPending > 0) && <Typography color="text.secondary">Поставлено в очередь Telegram: {alert.telegramQueued} · Ожидает настройки/отправки в очередь: {alert.telegramPending}</Typography>}
            {alert.deliveryError && <Alert severity="warning">{alert.deliveryError} <a href="#/staff/notifications">Настроить уведомления</a></Alert>}
            <Stack direction="row" gap={1}><Button component={Link} to={`/collaboration?kind=product&id=${alert.productId}&view=tasks`}>Создать задачу на закупку</Button><Button component={Link} to="/warehouseReceipts">Оформить поступление</Button></Stack>
        </Stack></Paper>)}
        <Typography variant="h6">Пороги товаров</Typography><TextField label="Найти товар по названию или GTIN" value={query} onChange={event => setQuery(event.target.value)}/>
        <Typography color="text.secondary">Показаны первые 50 совпадений. Для нужного товара используйте поиск. Настройки меняет администратор компании.</Typography>
        {rules.isError && <Alert severity="error">Не удалось загрузить товары.</Alert>}{rules.isLoading && <CircularProgress/>}
        {rules.data?.map(rule => <Paper key={rule.productId} variant="outlined" sx={{p:2}}><Stack direction="row" justifyContent="space-between" alignItems="center" flexWrap="wrap"><div><Typography>{rule.name}</Typography><Typography color="text.secondary">{rule.gtin} · Остаток {rule.currentStock} · {rule.enabled ? `Порог ${rule.threshold}` : "Напоминание выключено"}</Typography></div><Button disabled={!isCompanyAdmin} onClick={() => open(rule)}>Настроить порог</Button></Stack></Paper>)}
        <Dialog open={editing !== null} onClose={() => {if (!state.isLoading) setEditing(null);}} fullWidth maxWidth="sm"><DialogTitle>Напоминание о закупке</DialogTitle><DialogContent><Stack spacing={2} mt={1}>
            <Typography>{editing?.name}</Typography>{error && <Alert severity="error">{error}</Alert>}
            <FormControlLabel label="Включить напоминание" control={<Checkbox checked={editing?.enabled || false} onChange={event => setEditing(current => current && {...current,enabled:event.target.checked})}/>}/>
            <TextField label="Напомнить при остатке ≤" value={threshold} inputProps={{inputMode:"decimal"}} onChange={event => setThreshold(event.target.value)}/>
            <FormControlLabel label="Также отправлять в Telegram" control={<Checkbox checked={editing?.notifyTelegram || false} onChange={event => setEditing(current => current && {...current,notifyTelegram:event.target.checked})}/>}/>
            {editing?.notifyTelegram && <>{recipients.isError && <Alert severity="error">Не удалось загрузить получателей. <Button onClick={() => void recipients.refetch()}>Повторить</Button></Alert>}<Autocomplete multiple options={recipients.data || []} value={(recipients.data || []).filter(person => editing.recipientUserIds.includes(person.id))} getOptionLabel={person => `${person.name}${person.telegramReady ? "" : " — Telegram не подключён"}`} isOptionEqualToValue={(a,b) => a.id === b.id}
                onChange={(_,values) => setEditing(current => current && {...current,recipientUserIds:values.map(person => person.id)})} renderInput={params => <TextField {...params} label="Кому напомнить"/>}/>
                <Typography color="text.secondary">Получатели подключают личный Telegram через «Персонал → Уведомления». Если подключение ещё не готово, CRM сохранит напоминание и повторит постановку в очередь после настройки.</Typography></>}
        </Stack></DialogContent><DialogActions><Button disabled={state.isLoading} onClick={() => setEditing(null)}>Отмена</Button><Button variant="contained" disabled={state.isLoading} onClick={() => void commit()}>Сохранить</Button></DialogActions></Dialog>
    </Stack></MainDiv>;
}
